import review from './terminal-growth-review-data.js';
import {selectedGrowthPercentages} from './goog-selected-scenario-data.js';
import {getLocale,onLocaleChange,escapeLocalizedText as esc} from './i18n.js';
import {mountLocaleControl} from './i18n-control.js';
const copy={
 en:{title:'Terminal-growth review',classification:review.classification,scope:'Original annual paths, capital budgets, WACC, ROIC, claim adjustments and valuation dates remain unchanged by the terminal review.',real:'At an illustrative 2% inflation anchor, 3.0% nominal USD implies approximately 0.98% real growth; 2.5% implies approximately 0.49%. PCE inflation is not a company price index. Evidence does not uniquely identify 3.0%.',sources:'Methodology and dated sources',undated:'Undated methodology',twd:'The 4.0647% TWD rate reference is synthetic, using the existing 1.5% TWD and 2% USD long-run inflation assumptions with the 5.09% USD Treasury reference. It is not an observed Taiwan bond yield. Taiwan near-term CPI does not validate the long-run assumption.',selected:'Selected Google case',selectedBody:'The selected case uses the exact audited 20-year annual path, 35% operating margin by year 5, 10% WACC, 16% terminal ROIC and 3% terminal growth. Annual source-calendar investment floors and funded expansion are retained.',selectedValues:'June 30 conditional per-share allocations: selected case $306.616907; original case $210.132522; terminal-only reviewed comparison $214.860845.',selectedCaution:'The last explicit year still grows 2.5%, followed by 3% continuation. These are selected scenario assumptions with unresolved-claim limitations, not new issuer guidance or an October valuation. Use the comparison action or original-operating-path action to inspect the alternatives.',early:`First-three-year revenue growth, calculated from the exact annual rows: ${selectedGrowthPercentages.join('%, ')}%.`,sensitivity:'Sensitivity endpoints',scenario:'Analyst scenarios, not confidence intervals.',companyEvidence:'Company evidence; original research cutoff: 2026-10-17',frozen:'Frozen source',json:'Machine-readable review',back:'Back to valuation',roles:review.sources.map(s=>s.role)},
 'zh-Hans':{title:'终值增长率复核',classification:'分析师情景判断，并非 Damodaran 指定值或公司预测。模型支持可选的年度及终值不确定性；研究默认将终值增长率固定为复核值。复核日期不是新的估值日期。',scope:'终值复核保留原年度路径、资本预算、WACC、ROIC、债权调整和估值日期。',real:'以 2% 通胀作示例，3.0% 美元名义增长约等于 0.98% 实际增长；2.5% 约等于 0.49%。PCE 通胀不是公司价格指数；证据并不唯一确定 3.0%。',sources:'方法与来源日期',undated:'无日期方法说明',twd:'新台币 4.0647% 参考利率由原有长期通胀假设（新台币 1.5%、美元 2%）和美元国债参考值 5.09% 合成，并非台湾实际债券收益率。台湾短期 CPI 不足以验证长期通胀假设。',selected:'已选 Google 情景',selectedBody:'当前所选情景采用精确复核的 20 年年度路径，第 5 年经营利润率达到 35%，WACC 为 10%，终值 ROIC 为 16%，终值增长率为 3%。保留原日历年度投资下限及扩张资金需求。',selectedValues:'6 月 30 日有条件每股分配值：所选情景 $306.616907；原始情景 $210.132522；仅调整终值的研究比较值 $214.860845。',selectedCaution:'最后明确预测年度仍增长 2.5%，随后永续增长 3%。这些为所选情景假设，仍受未估值索偿权限制，并非新公司指引或十月估值。可用比较操作或恢复原经营路径操作检查替代方案。',early:`根据精确年度行计算的前三年收入增长率：${selectedGrowthPercentages.join('%、')}%。`,sensitivity:'敏感性端点',scenario:'分析师情景，并非置信区间。',companyEvidence:'公司证据；原始研究截止日：2026-10-17',frozen:'冻结来源',json:'结构化复核',back:'返回估值',roles:['方法说明，其中包含无日期的历史示例，并非当前宏观预测。','美元长期通胀及美国实际经济背景；PCE 通胀不是 GDP 平减指数，政策利率不是十年期无风险利率。','截至 10 月 18 日独立核实的最新可用观测值；仅作上限参考，并非永续增长建议。','仅为短期通胀背景，不能验证 1.5% 新台币长期通胀假设，也不构成终值增长预测。','仅为短期全球实际增长背景；这两个数值都不是永续美元或新台币名义增长率。不要将全球总体通胀加到美元现金流增长率上。']}
};
const link=(url,label)=>`<a href="${esc(url)}">${esc(label)}</a>`;
const pct=value=>String(Math.round(value*10000)/100);
export function terminalReviewPageHTML(locale='en'){
 const c=copy[locale]||copy.en,zh=locale==='zh-Hans';
 return `<p>${link('../index.html',c.back)}</p><h1>${esc(c.title)}</h1><p><time datetime="2026-10-18">2026-10-18</time> · ${esc(c.classification)}</p><p>${esc(c.scope)}</p><p>${esc(c.real)}</p><h2>${esc(c.sources)}</h2>${review.sources.map((source,index)=>`<p>${link(source.url,`${source.id} · ${source.date||c.undated}`)}<br>${esc(c.roles[index])}</p>`).join('')}<p>${esc(c.twd)}</p><section id="selected-GOOG"><h2>${esc(c.selected)}</h2><p>${esc(c.selectedBody)}</p><p>${esc(c.early)}</p><p>${esc(c.selectedValues)}</p><p>${esc(c.selectedCaution)}</p></section>${review.recommendations.map(row=>`<section id="${esc(row.ticker)}"><h2><span lang="en">${esc(row.ticker)} · ${pct(row.currentTerminalGrowth)}% → ${pct(row.recommendedTerminalGrowth)}% ${esc(row.currency)}</span></h2><p>${esc(zh?row.reasonZhHans:row.reason)}</p><p>${esc(zh?row.transitionZhHans:row.transition)}</p><p>${esc(c.sensitivity)}: ${pct(row.sensitivityRange.low)}%–${pct(row.sensitivityRange.high)}%. ${esc(c.scenario)}</p><p>${esc(c.companyEvidence)}</p><ul>${row.companySourceURLs.map(url=>`<li lang="en">${link(url,url)}</li>`).join('')}</ul></section>`).join('')}<p>${esc(c.frozen)}: ${link('studio-research-presets-2026-10-17-v1.json',review.sourcePreset)}<br><span lang="en">SHA-256: ${esc(review.sourceSHA256)}</span></p><p>${link('terminal-growth-review-2026-10-18-v1.json',c.json)}</p>`;
}
export function mountTerminalReviewPage(document=globalThis.document){
 const root=document?.getElementById('terminal-review-page');if(!root)return;
 const refresh=()=>{const locale=getLocale();root.innerHTML=terminalReviewPageHTML(locale);root.setAttribute('lang',locale);document.documentElement.lang=locale;document.title=copy[locale].title+' · 2026-10-18';};
 refresh();mountLocaleControl(document);return onLocaleChange(refresh);
}
if(typeof document!=='undefined')mountTerminalReviewPage(document);
